   const t=i/sampleRate,beat=Math.floor(t/.5),phase=t% .5,note=notes[beat%notes.length],env=Math.exp(-phase*5)*(1-Math.exp(-phase*80)),fade=Math.min(1,t/.4,(duration-t)/.6);
